import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import { edit_organization } from "@/graphql/mutations.js";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { datacorrection_comments_list_edit } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import Snackbar from "@/components/SnackBar.vue";
export default {
  mixins: [get_all_org_users, get_Org_details],
  components: {
    Snackbar
  },
  data: () => ({
    SnackBarComponent: {},
    loading: false,
    loadingapprove: false,
    datacorrection_id: "",
    selectedMember: "",
    userList: [],
    search: "",
    approvalAction: "yes",
    rules_datacorrect: [v => v.length != 0 || "DataCorrection Reason cannot be empty", v => /^[a-z\sA-Z]{1,30}$/.test(v) || "DataCorrection Reason cannot contain special characters "],
    corection_data: [],
    approvalData: [],
    dataObj: {},
    dataitem_datacorrection: []
  }),
  async created() {
    await this.get_list();
    await this.get_all_org_users();
    await this.get_Org_details();
    this.fetch_users();
  },
  methods: {
    fecth_updated_list() {
      this.approvalData.forEach(element => {
        if (element.name == this.dataObj.name) {
          if (this.approvalAction == "yes" && element.approvers_list.length != 0) {
            element.approvers_list[0].user_email_id = this.selectedMember;
            element.is_approval = true;
          } else if (this.approvalAction == "yes" && element.approvers_list.length == 0) {
            element.approvers_list = [{
              step_no: 1,
              user_email_id: this.selectedMember
            }];
            element.is_approval = true;
          } else {
            element.approvers_list = [];
            element.is_approval = false;
          }
        }
      });
      return JSON.stringify(this.approvalData);
    },
    async validate_data() {
      if (this.$refs.form1.validate()) {
        this.approval_actions();
      }
    },
    async approval_actions() {
      this.loadingapprove = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_organization, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            member_management_settings: await this.fecth_updated_list()
          }
        }));
        var response = JSON.parse(result.data.edit_organization);
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "Updated Successfully",
            timeout: 5000,
            Top: true
          };
          this.loadingapprove = false;
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.loadingapprove = false;
        }
      } catch (error) {
        this.loadingapprove = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    fetch_users() {
      this.userList = [];
      this.approvalData = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            title: element.full_user_name,
            value: element.user_email_id
          });
        }
      });
      this.userList.sort((a, b) => a.title.localeCompare(b.title));
      this.approvalData = this.orgDetails.organization.member_management_settings;
      let approvals;
      approvals = this.orgDetails.organization.member_management_settings;
      this.dataObj = approvals.find(item => item.name === "DATA_CORRECTION");
      this.approvalAction = this.dataObj.is_approval == true ? "yes" : "no";
      if (this.dataObj.is_approval == true) {
        this.selectedMember = this.dataObj.approvers_list[0].user_email_id;
      } else {
        this.selectedMember = "";
      }
    },
    async save_datacorrection() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(datacorrection_comments_list_edit, {
          input: {
            organization_id: data.organization.organization_id,
            datacorrection_comments: this.dataitem_datacorrection.map(val => {
              return val.name;
            }),
            datacorrection_id: this.datacorrection_id,
            action_type: "EDIT"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.datacorrection_comments_list_edit);
        // console.log(response);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.loading = false;
      }
    },
    async get_list() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(datacorrection_comments_list_edit, {
          input: {
            organization_id: data.organization.organization_id,
            datacorrection_comments: this.dataitem_datacorrection.map(val => {
              return val.name;
            }),
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.datacorrection_comments_list_edit);
        this.dataitem_datacorrection = response.data.datacorrection_comments.map((val, i) => {
          return {
            name: val,
            index: i
          };
        });
        this.datacorrection_id = response.data.datacorrection_id;
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async add_datacorrection(corection_data) {
      const formValidation = await this.$refs.form.validate();
      if (formValidation.valid) {
        const trimmedData = (corection_data || "").toString().trim();
        if (!trimmedData) {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            Top: true,
            SnackbarText: "Please enter a valid Data Correction Reason"
          };
          return;
        }
        const hasMatchingCode = this.dataitem_datacorrection.some(obj => obj.name.toLowerCase() === trimmedData.toLowerCase());
        if (!hasMatchingCode) {
          this.dataitem_datacorrection.push({
            name: trimmedData
          });
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            Top: true,
            SnackbarText: "Data Correction Reason added successfully"
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            Top: true,
            SnackbarText: "Data Correction Reason already exists"
          };
        }
        this.corection_data = "";
        this.$refs.form.resetValidation();
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          Top: true,
          SnackbarText: "Please fill the required field."
        };
      }
    },
    delete_feature_data_correction(item) {
      for (let i = 0; i < this.dataitem_datacorrection.length; i++) {
        if (item.name == this.dataitem_datacorrection[i].name) {
          this.dataitem_datacorrection.splice(i, 1);
        }
      }
    }
  }
};
